const propostasDocumentosJS={init:function(){this.initFormUpload();this.initDeleteButtons()},initFormUpload:function(){$("#UploadArquivo").customDropzone({url:"/PropostasDocumentos/UploadFile",maxFiles:1,maxFilesize:50,addRemoveLinks:!0,autoQueue:!0,onSending:function(n){console.log("Enviando arquivo: "+n.name)},onQueueComplete:function(){console.log("Upload completo!")},onSuccess:function(n,t){t.success?($("#formUploadDocumento input[name=ArquivoBase64]").val(t.data),$("#formUploadDocumento input[name=ArquivoNome]").val(t.nome),$("#formUploadDocumento input[name=ArquivoPath]").val(t.path)):(console.error("Erro no upload: "+t.message),notify.error("Erro no Upload",t.message))},onError:function(n,t){console.error("Erro no upload do arquivo "+n.name+": "+t);notify.error("Erro no Upload",t)}})},onSuccessCallbackDocumento:function(n){if(n.success==!0){var t=$("#formUploadDocumento select[name=TipoDocumento]").val();$("#formUploadDocumento input[name=ArquivoBase64]").val("");$("#formUploadDocumento input[name=ArquivoNome]").val("");$("#formUploadDocumento input[name=ArquivoPath]").val("");$("#formUploadDocumento select[name=TipoDocumento]").val("");propostasDocumentosJS.refreshDocumentos();t==="Boleto"&&setTimeout(function(){typeof propostaJS!="undefined"&&propostaJS.refreshTimeline&&propostaJS.refreshTimeline()},1e3);setTimeout(function(){typeof propostaJS!="undefined"&&propostaJS.atualizarStatusAbas&&propostaJS.atualizarStatusAbas()},500);notify.success("Documento",n.message,null)}else notify.error("Atenção",n.message)},refreshDocumentos:function(){gl.RenderGet("PropostasDocumentos","Propostas",{propostaId:$("#PropostaId").val()},"#documento_container",!0,null,function(){propostasDocumentosJS.initDeleteButtons();setTimeout(function(){typeof propostaJS!="undefined"&&propostaJS.atualizarStatusAbas&&propostaJS.atualizarStatusAbas()},300)})},initDeleteButtons:function(){$(".excluir-documento").off("click").on("click",function(){const n=$(this).data("id"),t=$(this).data("nome");propostasDocumentosJS.confirmarRemoverDocumento(n,t)})},confirmarRemoverDocumento:function(n,t){notify.confirmYesNo("danger","Confirmação de Exclusão","Tem certeza que deseja excluir este documento: "+t+"?",function(t){t&&gl.Post("Excluir","PropostasDocumentos",{documentoId:n,__RequestVerificationToken:gl.GetToken()},!0,function(n){n.success?(propostasDocumentosJS.refreshDocumentos(),setTimeout(function(){typeof propostaJS!="undefined"&&propostaJS.atualizarStatusAbas&&propostaJS.atualizarStatusAbas()},500),notify.success("Documentos",n.message||"Documento excluído com sucesso!",null)):notify.error("Atenção",n.message||"Erro ao excluir documento.")},function(){notify.error("Erro AJAX","Falha ao tentar excluir o documento. Verifique o console.")})},null,"Sim, remover","Cancelar")}};